import type { AtRule } from "postcss";
import type { AtRuleVariableValue } from "../../index.ts";
/**
 * Finds the value of a Less variable declaration in the copies `postcss-less` split it over.
 *
 * The parser marks the node `variable` only where the colon closed the name, and leaves the colon at the head of the params where the name ended in front of it; both keep the whole value in the params. Where the at-word ran on past the colon, the word behind it is welded into the name — `@v:10PX 1px` comes back named `v:10PX` with `1px` for params, `@v:url(10PX)` named `v:url` with the nameless group `(10PX)` — so the value is gathered from the name, the raw behind it and the params, which is contiguous in the printed node.
 *
 * A block shuts the two unmarked readings: `@page:first { … }` spells a colon in its name and is an at-rule of CSS. A marked node with a block is a detached ruleset, whose params hold whatever stands in front of the brace, and is read as it always was.
 * @param atRule - The at-rule.
 * @returns The value, or `null` where Less declares no variable with this at-rule.
 */
export declare function atRuleVariableValue(atRule: AtRule): AtRuleVariableValue | null;
